/**
*@filelibavfilteraudiofilteringAPIusageexample
*@examplefilter_audio.c
*
*Thisexamplewillgenerateasinewaveaudio,passitthroughasimplefilter
*chain,andthencomputetheMD5checksumoftheoutputdata.
*
*Thefilterchainitusesis:
*(input)->abuffer->volume->aformat->abuffersink->(output)
*
*abuffer:Thisprovidestheendpointwhereyoucanfeedthedecodedsamples.
*volume:Inthisexamplewehardcodeitto0.90.
*aformat:Thisconvertsthesamplestothesamplefreq,channellayout,
*andsampleformatrequiredbytheaudiodevice.
*abuffersink:Thisprovidestheendpointwhereyoucanreadthesamplesafter
*theyhavepassedthroughthefilterchain.
*/

#include<inttypes.h>
#include<math.h>
#include<stdio.h>
#include<stdlib.h>

#include<libavutil/channel_layout.h>
#include<libavutil/md5.h>
#include<libavutil/mem.h>
#include<libavutil/opt.h>
#include<libavutil/samplefmt.h>

#include<libavfilter/avfilter.h>
#include<libavfilter/buffersink.h>
#include<libavfilter/buffersrc.h>

#defineINPUT_SAMPLERATE48000
#defineINPUT_FORMATAV_SAMPLE_FMT_FLTP
#defineINPUT_CHANNEL_LAYOUT(AVChannelLayout)AV_CHANNEL_LAYOUT_5POINT0

#defineVOLUME_VAL0.90

staticintinit_filter_graph(AVFilterGraph**graph,AVFilterContext**src,
AVFilterContext**sink)
{
AVFilterGraph*filter_graph;
AVFilterContext*abuffer_ctx;
constAVFilter*abuffer;
AVFilterContext*volume_ctx;
constAVFilter*volume;
AVFilterContext*aformat_ctx;
constAVFilter*aformat;
AVFilterContext*abuffersink_ctx;
constAVFilter*abuffersink;

AVDictionary*options_dict=NULL;
uint8_toptions_str[1024];
uint8_tch_layout[64];

interr;

/*Createanewfiltergraph,whichwillcontainallthefilters.*/
filter_graph=avfilter_graph_alloc();
if(!filter_graph){
fprintf(stderr,"Unabletocreatefiltergraph.\n");
returnAVERROR(ENOMEM);
}

/*Createtheabufferfilter;
*itwillbeusedforfeedingthedataintothegraph.*/
abuffer=avfilter_get_by_name("abuffer");
if(!abuffer){
fprintf(stderr,"Couldnotfindtheabufferfilter.\n");
returnAVERROR_FILTER_NOT_FOUND;
}

abuffer_ctx=avfilter_graph_alloc_filter(filter_graph,abuffer,"src");
if(!abuffer_ctx){
fprintf(stderr,"Couldnotallocatetheabufferinstance.\n");
returnAVERROR(ENOMEM);
}

/*SetthefilteroptionsthroughtheAVOptionsAPI.*/
av_channel_layout_describe(&INPUT_CHANNEL_LAYOUT,ch_layout,sizeof(ch_layout));
av_opt_set(abuffer_ctx,"channel_layout",ch_layout,AV_OPT_SEARCH_CHILDREN);
av_opt_set(abuffer_ctx,"sample_fmt",av_get_sample_fmt_name(INPUT_FORMAT),AV_OPT_SEARCH_CHILDREN);
av_opt_set_q(abuffer_ctx,"time_base",(AVRational){1,INPUT_SAMPLERATE},AV_OPT_SEARCH_CHILDREN);
av_opt_set_int(abuffer_ctx,"sample_rate",INPUT_SAMPLERATE,AV_OPT_SEARCH_CHILDREN);

/*Nowinitializethefilter;wepassNULLoptions,sincewehavealready
*setalltheoptionsabove.*/
err=avfilter_init_str(abuffer_ctx,NULL);
if(err<0){
fprintf(stderr,"Couldnotinitializetheabufferfilter.\n");
returnerr;
}

/*Createvolumefilter.*/
volume=avfilter_get_by_name("volume");
if(!volume){
fprintf(stderr,"Couldnotfindthevolumefilter.\n");
returnAVERROR_FILTER_NOT_FOUND;
}

volume_ctx=avfilter_graph_alloc_filter(filter_graph,volume,"volume");
if(!volume_ctx){
fprintf(stderr,"Couldnotallocatethevolumeinstance.\n");
returnAVERROR(ENOMEM);
}

/*Adifferentwayofpassingtheoptionsisaskey/valuepairsina
*dictionary.*/
av_dict_set(&options_dict,"volume",AV_STRINGIFY(VOLUME_VAL),0);
err=avfilter_init_dict(volume_ctx,&options_dict);
av_dict_free(&options_dict);
if(err<0){
fprintf(stderr,"Couldnotinitializethevolumefilter.\n");
returnerr;
}

/*Createtheaformatfilter;
*itensuresthattheoutputisoftheformatwewant.*/
aformat=avfilter_get_by_name("aformat");
if(!aformat){
fprintf(stderr,"Couldnotfindtheaformatfilter.\n");
returnAVERROR_FILTER_NOT_FOUND;
}

aformat_ctx=avfilter_graph_alloc_filter(filter_graph,aformat,"aformat");
if(!aformat_ctx){
fprintf(stderr,"Couldnotallocatetheaformatinstance.\n");
returnAVERROR(ENOMEM);
}

/*Athirdwayofpassingtheoptionsisinastringoftheform
*key1=value1:key2=value2....*/
snprintf(options_str,sizeof(options_str),
"sample_fmts=%s:sample_rates=%d:channel_layouts=stereo",
av_get_sample_fmt_name(AV_SAMPLE_FMT_S16),44100);
err=avfilter_init_str(aformat_ctx,options_str);
if(err<0){
av_log(NULL,AV_LOG_ERROR,"Couldnotinitializetheaformatfilter.\n");
returnerr;
}

/*Finallycreatetheabuffersinkfilter;
*itwillbeusedtogetthefiltereddataoutofthegraph.*/
abuffersink=avfilter_get_by_name("abuffersink");
if(!abuffersink){
fprintf(stderr,"Couldnotfindtheabuffersinkfilter.\n");
returnAVERROR_FILTER_NOT_FOUND;
}

abuffersink_ctx=avfilter_graph_alloc_filter(filter_graph,abuffersink,"sink");
if(!abuffersink_ctx){
fprintf(stderr,"Couldnotallocatetheabuffersinkinstance.\n");
returnAVERROR(ENOMEM);
}

/*Thisfiltertakesnooptions.*/
err=avfilter_init_str(abuffersink_ctx,NULL);
if(err<0){
fprintf(stderr,"Couldnotinitializetheabuffersinkinstance.\n");
returnerr;
}

/*Connectthefilters;
*inthissimplecasethefiltersjustformalinearchain.*/
err=avfilter_link(abuffer_ctx,0,volume_ctx,0);
if(err>=0)
err=avfilter_link(volume_ctx,0,aformat_ctx,0);
if(err>=0)
err=avfilter_link(aformat_ctx,0,abuffersink_ctx,0);
if(err<0){
fprintf(stderr,"Errorconnectingfilters\n");
returnerr;
}

/*Configurethegraph.*/
err=avfilter_graph_config(filter_graph,NULL);
if(err<0){
av_log(NULL,AV_LOG_ERROR,"Errorconfiguringthefiltergraph\n");
returnerr;
}

*graph=filter_graph;
*src=abuffer_ctx;
*sink=abuffersink_ctx;

return0;
}

/*Dosomethingusefulwiththefiltereddata:thissimple
*examplejustprintstheMD5checksumofeachplanetostdout.*/
staticintprocess_output(structAVMD5*md5,AVFrame*frame)
{
intplanar=av_sample_fmt_is_planar(frame->format);
intchannels=frame->ch_layout.nb_channels;
intplanes=planar?channels:1;
intbps=av_get_bytes_per_sample(frame->format);
intplane_size=bps*frame->nb_samples*(planar?1:channels);
inti,j;

for(i=0;i<planes;i++){
uint8_tchecksum[16];

av_md5_init(md5);
av_md5_sum(checksum,frame->extended_data[i],plane_size);

fprintf(stdout,"plane%d:0x",i);
for(j=0;j<sizeof(checksum);j++)
fprintf(stdout,"%02X",checksum[j]);
fprintf(stdout,"\n");
}
fprintf(stdout,"\n");

return0;
}

/*Constructaframeofaudiodatatobefiltered;
*thissimpleexamplejustsynthesizesasinewave.*/
staticintget_input(AVFrame*frame,intframe_num)
{
interr,i,j;

#defineFRAME_SIZE1024

/*Setuptheframepropertiesandallocatethebufferforthedata.*/
frame->sample_rate=INPUT_SAMPLERATE;
frame->format=INPUT_FORMAT;
av_channel_layout_copy(&frame->ch_layout,&INPUT_CHANNEL_LAYOUT);
frame->nb_samples=FRAME_SIZE;
frame->pts=frame_num*FRAME_SIZE;

err=av_frame_get_buffer(frame,0);
if(err<0)
returnerr;

/*Fillthedataforeachchannel.*/
for(i=0;i<5;i++){
float*data=(float*)frame->extended_data[i];

for(j=0;j<frame->nb_samples;j++)
data[j]=sin(2*M_PI*(frame_num+j)*(i+1)/FRAME_SIZE);
}

return0;
}

intmain(intargc,char*argv[])
{
structAVMD5*md5;
AVFilterGraph*graph;
AVFilterContext*src,*sink;
AVFrame*frame;
floatduration;
interr,nb_frames,i;

if(argc<2){
fprintf(stderr,"Usage:%s<duration>\n",argv[0]);
return1;
}

duration=atof(argv[1]);
nb_frames=duration*INPUT_SAMPLERATE/FRAME_SIZE;
if(nb_frames<=0){
fprintf(stderr,"Invalidduration:%s\n",argv[1]);
return1;
}

/*Allocatetheframewewillbeusingtostorethedata.*/
frame=av_frame_alloc();
if(!frame){
fprintf(stderr,"Errorallocatingtheframe\n");
return1;
}

md5=av_md5_alloc();
if(!md5){
fprintf(stderr,"ErrorallocatingtheMD5context\n");
return1;
}

/*Setupthefiltergraph.*/
err=init_filter_graph(&graph,&src,&sink);
if(err<0){
fprintf(stderr,"Unabletoinitfiltergraph:");
gotofail;
}

/*themainfilteringloop*/
for(i=0;i<nb_frames;i++){
/*getaninputframetobefiltered*/
err=get_input(frame,i);
if(err<0){
fprintf(stderr,"Errorgeneratinginputframe:");
gotofail;
}

/*Sendtheframetotheinputofthefiltergraph.*/
err=av_buffersrc_add_frame(src,frame);
if(err<0){
av_frame_unref(frame);
fprintf(stderr,"Errorsubmittingtheframetothefiltergraph:");
gotofail;
}

/*Getallthefilteredoutputthatisavailable.*/
while((err=av_buffersink_get_frame(sink,frame))>=0){
/*nowdosomethingwithourfilteredframe*/
err=process_output(md5,frame);
if(err<0){
fprintf(stderr,"Errorprocessingthefilteredframe:");
gotofail;
}
av_frame_unref(frame);
}

if(err==AVERROR(EAGAIN)){
/*Needtofeedmoreframesin.*/
continue;
}elseif(err==AVERROR_EOF){
/*Nothingmoretodo,finish.*/
break;
}elseif(err<0){
/*Anerroroccurred.*/
fprintf(stderr,"Errorfilteringthedata:");
gotofail;
}
}

avfilter_graph_free(&graph);
av_frame_free(&frame);
av_freep(&md5);

return0;

fail:
fprintf(stderr,"%s\n",av_err2str(err));
return1;
}
